// <autogenerated />
using Microsoft.Build.Framework;
using Microsoft.Build.Utilities;
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;

/// <summary>
/// Creates pre-compressed (.br / .gz) versions of files to publish, like the static web assets SDK
/// does for its assets, using the same CompressionIncludePatterns / CompressionExcludePatterns /
/// PublishCompressionFormats semantics. Compressed files are cached in IntermediateDirectory, and
/// only recreated when the source file changes. Like the SDK, a compressed file is always produced,
/// even when it is not smaller, so a newer publish never leaves an older compressed version of a
/// file next to it. Brotli is only available when MSBuild runs on .NET (e.g. dotnet build).
/// </summary>
public class CompressStaticAssetsTask : Microsoft.Build.Utilities.Task
{
    /// <summary>Files with a RelativePath (publish relative) metadata, optionally with a
    /// CompressionExcludePatterns metadata (patterns relative to AssetPath metadata) from their library</summary>
    [Microsoft.Build.Framework.Required]
    public ITaskItem[] Files { get; set; }

    [Microsoft.Build.Framework.Required]
    public string IntermediateDirectory { get; set; }

    /// <summary>Prefix of RelativePath to strip before matching patterns, e.g. "wwwroot"</summary>
    public string PatternRoot { get; set; }

    public string IncludePatterns { get; set; }

    public string ExcludePatterns { get; set; }

    /// <summary>gzip, brotli or both</summary>
    public string Formats { get; set; }

    [Microsoft.Build.Framework.Output]
    public ITaskItem[] CompressedFiles { get; set; }

    public override bool Execute()
    {
        var formats = Split(Formats).Select(x => x.ToLowerInvariant()).Distinct().ToList();
        var brotliType = formats.Contains("brotli") ?
            Type.GetType("System.IO.Compression.BrotliStream, System.IO.Compression.Brotli", throwOnError: false) : null;
        if (formats.Contains("brotli") && brotliType == null)
            Log.LogMessage(MessageImportance.Normal, "Brotli is not available in this MSBuild runtime, only gzip files will be created.");

        // SmallestSize is only defined on .NET
        var level = Enum.IsDefined(typeof(CompressionLevel), 3) ? (CompressionLevel)3 : CompressionLevel.Optimal;

        var includes = Split(IncludePatterns).Select(GlobToRegex).ToArray();
        var excludes = Split(ExcludePatterns).Select(GlobToRegex).ToArray();
        var libraryExcludes = new ConcurrentDictionary<string, Regex[]>(StringComparer.Ordinal);

        var existing = new HashSet<string>(Files.Select(x => Normalize(x.GetMetadata("RelativePath"))),
            StringComparer.OrdinalIgnoreCase);

        var extensions = new List<KeyValuePair<string, Func<Stream, Stream>>>();
        if (brotliType != null)
            extensions.Add(new KeyValuePair<string, Func<Stream, Stream>>(".br",
                s => (Stream)Activator.CreateInstance(brotliType, s, level)));
        if (formats.Contains("gzip"))
            extensions.Add(new KeyValuePair<string, Func<Stream, Stream>>(".gz",
                s => new GZipStream(s, level)));

        var results = new ConcurrentBag<ITaskItem>();
        var created = 0;
        if (extensions.Count == 0)
        {
            CompressedFiles = new ITaskItem[0];
            return true;
        }

        var patternRoot = Normalize(PatternRoot ?? "").Trim('/');

        // the same publish path may be listed more than once, process each only once
        var files = Files
            .GroupBy(x => Normalize(x.GetMetadata("RelativePath")), StringComparer.OrdinalIgnoreCase)
            .Select(x => x.First())
            .ToArray();

        Parallel.ForEach(files, file =>
        {
            var relativePath = Normalize(file.GetMetadata("RelativePath"));
            var patternPath = relativePath;
            if (patternRoot.Length > 0 && patternPath.StartsWith(patternRoot + "/", StringComparison.OrdinalIgnoreCase))
                patternPath = patternPath.Substring(patternRoot.Length + 1);

            if (!includes.Any(x => x.IsMatch(patternPath)) ||
                excludes.Any(x => x.IsMatch(patternPath)))
                return;

            var libraryPatterns = file.GetMetadata("CompressionExcludePatterns");
            if (!string.IsNullOrWhiteSpace(libraryPatterns))
            {
                var assetPath = Normalize(file.GetMetadata("AssetPath"));
                if (string.IsNullOrEmpty(assetPath))
                    assetPath = patternPath;

                var regexes = libraryExcludes.GetOrAdd(libraryPatterns, p => Split(p).Select(GlobToRegex).ToArray());
                if (regexes.Any(x => x.IsMatch(assetPath)))
                    return;
            }

            // empty files are skipped, GZipStream would not even write a valid (empty) gzip stream for them
            var source = file.GetMetadata("FullPath");
            if (!File.Exists(source) || new FileInfo(source).Length == 0)
                return;

            foreach (var pair in extensions)
            {
                // e.g. already compressed by the static web assets SDK, or a pre-compressed source file
                if (existing.Contains(relativePath + pair.Key))
                    continue;

                var target = Path.Combine(IntermediateDirectory, relativePath.Replace('/', Path.DirectorySeparatorChar) + pair.Key);
                try
                {
                    if (!File.Exists(target) ||
                        File.GetLastWriteTimeUtc(target) < File.GetLastWriteTimeUtc(source))
                    {
                        Directory.CreateDirectory(Path.GetDirectoryName(target));
                        var temp = target + ".tmp";
                        using (var input = File.OpenRead(source))
                        using (var output = File.Create(temp))
                        using (var compressor = pair.Value(output))
                            input.CopyTo(compressor);

                        if (File.Exists(target))
                            File.Delete(target);

                        File.Move(temp, target);
                        System.Threading.Interlocked.Increment(ref created);
                    }

                    var item = new TaskItem(target);
                    item.SetMetadata("RelativePath", file.GetMetadata("RelativePath") + pair.Key);
                    item.SetMetadata("CopyToPublishDirectory", "PreserveNewest");
                    item.SetMetadata("ExcludeFromSingleFile", "true");
                    results.Add(item);
                }
                catch (Exception ex)
                {
                    Log.LogWarning("Couldn't compress {0}: {1}", source, ex.Message);
                }
            }
        });

        CompressedFiles = results.ToArray();
        Log.LogMessage(MessageImportance.Normal, "Compressed {0} file(s), {1} pre-compressed file(s) to publish.",
            created, CompressedFiles.Length);

        return !Log.HasLoggedErrors;
    }

    private static string Normalize(string path)
    {
        return (path ?? "").Replace('\\', '/');
    }

    private static IEnumerable<string> Split(string value)
    {
        return (value ?? "").Split(new[] { ';', '\r', '\n' }, StringSplitOptions.RemoveEmptyEntries)
            .Select(x => x.Trim())
            .Where(x => x.Length > 0);
    }

    private static Regex GlobToRegex(string pattern)
    {
        var p = Normalize(pattern).TrimStart('/');
        var sb = new System.Text.StringBuilder("^");
        for (var i = 0; i < p.Length; i++)
        {
            var c = p[i];
            if (c == '*')
            {
                if (i + 1 < p.Length && p[i + 1] == '*')
                {
                    i++;
                    if (i + 1 < p.Length && p[i + 1] == '/')
                    {
                        i++;
                        sb.Append("(.*/)?");
                    }
                    else
                        sb.Append(".*");
                }
                else
                    sb.Append("[^/]*");
            }
            else if (c == '?')
                sb.Append("[^/]");
            else
                sb.Append(Regex.Escape(c.ToString()));
        }

        sb.Append('$');
        return new Regex(sb.ToString(), RegexOptions.IgnoreCase | RegexOptions.CultureInvariant);
    }
}
